const x = $input.first().json.body || $input.first().json;
const prompt = `You are the OpenPulse editorial desk. Audience: broad intellectual interests including technology, AI, science, space, research, philosophy, history and culture.
Assess the candidate story. Return ONLY valid JSON with keys: category (technology, AI, science, space, research, philosophy, history, culture, other), relevance_score (integer 1-10), originality_angle (one sentence), audience_value (one sentence), risk_flags (array), decision (select or reject).
Be conservative. Reject thin, sensational, duplicate or low-value topics. Do not invent facts.
TITLE: ${x.title || ""}
SUMMARY: ${x.summary || ""}
SOURCE: ${x.link || ""}`;
return [{json:{prompt}}];

const raw = $input.first().json.response || "";
let result;
try { result = JSON.parse(raw); } catch (e) { result = {decision:"review",parse_error:true,raw}; }
return [{json:{...result,scored_at:new Date().toISOString()}}];
